, a section, or the component's `mode` prop */
[data-th-mode="night"] { --th-ink: #f2f0ea; --th-glass: #000000; --th-white: #121212; }
[data-th-mode="mono"] { --th-shell: #4a4a46; --th-glass: #121212; --th-alert: #f2f0ea; --th-ok: #f2f0ea; }
[data-th-mode="phosphor"] { --th-ink: #0b1a10; --th-shell: #2f7d5b; --th-glass: #06100a; --th-glyph: #9dffb0; --th-alert: #ffb35e; --th-ok: #9dffb0; }
/* A component without its own `mode` prop inherits the nearest parent's tokens. */

.th { display: inline-block; line-height: 0; flex-shrink: 0; vertical-align: middle; }
.th svg { display: block; overflow: visible; }

/* Colours */
.th-glass { fill: var(--th-glass); }
.th-c-k { fill: var(--th-ink); }
.th-c-y { fill: var(--th-shell); }
.th-c-r, .th-f-r { fill: var(--th-alert); }
.th-c-w { fill: var(--th-white); }
.th-c-q { fill: var(--th-steel); }
.th-f-e, .th-f-b, .th-f-c, .th-f-u, .th-f-v, .th-f-x { fill: var(--th-glyph); }
.th-f-g { fill: var(--th-ok); }

/* Motion — loops */
.th-spr, .th-f-b { transform-box: fill-box; }
.th-spr { transform-origin: 50% 100%; animation: th-bob 1.4s steps(2) infinite; }
.th-f-c { animation: th-blink 1s steps(1) infinite; }
.th-f-u { animation: th-dots 1.2s infinite; }
.th-f-v { animation: th-dots 1.2s .2s infinite; }
.th-f-x { animation: th-dots 1.2s .4s infinite; }
.th-f-b { transform-origin: 0% 50%; animation: th-fill 2.2s cubic-bezier(.4, 0, .2, 1) infinite; }
.th--found .th-spr, .th--error .th-spr { animation: th-shake .22s steps(2) 3; }
.th--love .th-spr { animation: th-pulse .9s ease-in-out infinite; }
.th--sleep .th-spr { animation: th-breathe 2.8s ease-in-out infinite; }
.th--fixed .th-spr { animation: th-bob 1.4s steps(2) 1; }

/* Motion — one-shots */
.th-face { animation: th-swap .16s steps(2) 1; }
.th--m-still .th-spr, .th--m-still .th-face, .th--m-still .th-face * { animation: none; }
.th--m-hop .th-spr { animation: th-hop .5s steps(5) 1; }
.th--m-peek { overflow: hidden; }
.th--m-peek .th-spr { animation: th-peek .4s steps(4) 1 both; }
.th--m-type .th-face { animation: th-type .24s steps(6) 1 both; }

@keyframes th-bob { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-.5px); } }
@keyframes th-blink { 0%, 49% { opacity: 1; } 50%, 100% { opacity: 0; } }
@keyframes th-dots { 0%, 100% { opacity: .15; } 30% { opacity: 1; } }
@keyframes th-fill { 0% { transform: scaleX(0); } 80%, 100% { transform: scaleX(1); } }
@keyframes th-shake { 0%, 100% { transform: translateX(-.4px); } 50% { transform: translateX(.4px); } }
@keyframes th-pulse { 0%, 100% { transform: scale(1); } 50% { transform: scale(1.04); } }
@keyframes th-breathe { 0%, 100% { transform: scale(1, 1); } 50% { transform: scale(1.015, .985); } }
@keyframes th-hop { 0% { transform: translateY(0); } 40% { transform: translateY(-3px); } 80% { transform: translateY(0) scale(1.05, .95); } 100% { transform: none; } }
@keyframes th-peek { from { transform: translateY(100%); } to { transform: translateY(0); } }
@keyframes th-swap { 0% { opacity: .2; } 50% { opacity: .7; } 100% { opacity: 1; } }
@keyframes th-type { from { clip-path: inset(0 0 100% 0); } to { clip-path: inset(0 0 0 0); } }

@media (prefers-reduced-motion: reduce){*{animation:none!important}}
